WITH gated AS (SELECT model FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model != '' GROUP BY model HAVING count() >= 100) SELECT concat(model, ' (p50)') AS metric, round(medianExactIf(completion_tokens / nullIf(duration_ms - ttft_content_ms, 0) * 1000, is_stream = 1 AND ttft_content_ms >= 100 AND duration_ms - ttft_content_ms >= 100), 2) AS value FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model != '' AND is_stream = 1 AND ttft_content_ms >= 100 AND duration_ms - ttft_content_ms >= 100 AND coalesce(nullIf(key_id,''), nullIf(api_key_id,''), 'unknown') IN ({{ gf_str_multi('api_key') }}) AND model IN ({{ gf_str_multi('model') }}) AND model IN (SELECT model FROM gated) GROUP BY model ORDER BY value DESC LIMIT 40